  function practice(c){
    let i=0,score=0,completed=0;
    const fullyScored=c.quiz.every(item=>Array.isArray(item.choices));
    const body=el("div");
    const count=el("p","gco-hub-meta");
    const q=el("h3");q.style.margin="8px 0";
    const opts=el("div","gco-hub-options");
    const feedback=el("div","gco-hub-feedback");feedback.hidden=true;
    body.append(count,q,opts,feedback);
    const d=showDialog("INTERACTIVE TOPIC PRACTICE",c.title,body);
    const foot=$("#gcoHubFoot",d);
    const next=btn("Next question →","gco-hub-btn",()=>{
      if(i<c.quiz.length-1){i++;draw();return;}
      q.textContent=fullyScored?`Complete: ${score}/${c.quiz.length} correct`:`Complete: ${completed}/${c.quiz.length} checks reviewed`;
      opts.replaceChildren();feedback.hidden=false;
      feedback.textContent=fullyScored?"Review the explanations, then repeat any question you missed.":"These questions use written responses, so GCSE ONTRACK shows a self-check guide rather than pretending to mark your written answer automatically.";
      next.disabled=true;
    });
    foot.append(el("span","gco-hub-meta",fullyScored?"Choose one answer.":"Answer in your own words, then reveal the self-check."),next);
    function draw(){
      const item=c.quiz[i];count.textContent=`Question ${i+1} of ${c.quiz.length}`;q.textContent=item.q||item.prompt;
      opts.replaceChildren();feedback.hidden=true;next.disabled=true;
      if(item.choices){
        item.choices.forEach((choice,n)=>opts.append(btn(choice,"gco-hub-option",()=>{
          const correct=n===item.a;if(correct)score++;completed++;
          [...opts.children].forEach((b,j)=>{b.disabled=true;if(j===item.a)b.style.borderColor="#16815f";});
          feedback.hidden=false;feedback.textContent=`${correct?"Correct. ":"Not quite. "}${item.why}`;next.disabled=false;
        })));
      }else{
        opts.append(el("p","gco-hub-meta",item.prompt));
        const area=document.createElement("textarea");area.rows=3;area.placeholder="Write your answer here…";
        area.style.cssText="width:100%;padding:10px;border:1px solid #d5dbe3;border-radius:8px";
        const reveal=btn("Show self-check","gco-hub-btn secondary",()=>{
          completed++;reveal.disabled=true;feedback.hidden=false;feedback.textContent=(item.check||[]).join(" · ");next.disabled=false;
        });
        opts.append(area,reveal);
      }
    }
    draw();
  }
