  function oldScriptGuards(card,s,board){
    const guide=[s.id||"",s.durationMinutes||"",s.subject||"",s.topic||"",board||""].join("|");
    const t=clean(s.topic,140).toLowerCase(),sub=subjectKey(s.subject);
    let id="unmapped";
    // Keep the earlier, still-active topic-guide observer from replacing this
    // panel. Match only where the legacy pack would also pass its board check.
    if(sub==="chemistry"&&board==="AQA"&&/simple model of (?:the )?atom|atomic structure|subatomic particles|isotopes|relative atomic mass|nuclear symbols|electronic charge|electron shells?|electronic structure|development of the (?:atomic|atom) model|plum pudding|alpha particle scattering|nuclear model/.test(t))id="chemistry-atomic-structure";
    else if(sub==="biology"&&board==="AQA"&&/cell structure|cell biology|animal and plant cells|prokaryot|eukaryot|organelles/.test(t))id="biology-cell-structure";
    else if(sub==="physics"&&board==="AQA"&&/atomic structure|atoms and isotopes|nuclear radiation|radioactive decay|electron shells|nuclear fission|nuclear fusion/.test(t))id="physics-atomic-structure";
    else if(sub==="maths"&&board==="Pearson Edexcel"&&/sequence|nth term|arithmetic sequence|linear sequence/.test(t))id="maths-sequences-edexcel";
    else if(sub==="history"&&board==="AQA"&&/rise of the nazis|nazi rise|hitler becomes chancellor|great depression.*nazi|nazi.*great depression|reichstag/.test(t))id="history-germany-1890-1945";
    else if(sub==="business"&&board==="Pearson Edexcel"&&/cash\s*flow|cashflow|cash inflow|cash outflow|cash-flow forecast/.test(t))id="business-cash-flow-edexcel";
    else if(sub==="english-language"&&board==="AQA"&&/paper ?1.*(question ?2|q2)|question ?2.*language|\bq2\b|language analysis|language effect/.test(t))id="english-language-paper1-q2";
    else if(sub==="english-literature"&&board==="AQA"&&/macbeth|lady macbeth|banquo|macduff|witches|ambition.*guilt|guilt.*ambition/.test(t))id="english-literature-macbeth";
    card.dataset.gcoTopicResourceKey=`${guide}|${id}`;
    card.dataset.refinedResourceKey=[s.id||"",s.topic||"",board||""].join("|");
    card.dataset.filteredResourceKey=guide;
  }
